// ONE observer · enforcement point · Cloudflare Worker
// Every request is evaluated against one program. Rows: manifest, epoch, identity, purpose, policy,
// context, lifecycle, score. Buckets: human · agent · unattributed. Every decision is a signed witness.
// Modes (KV key "mode"): observe (default, nothing blocked) · stepup (unattributed sessions on STEPUP_PATHS
// are sent to the presence page) · enforce (unattributed sessions on ENFORCE_PATHS get 403 and a witness).


// Demo custody: if no WITNESS_PRIVATE_JWK / PRESENCE_HMAC secret is configured, generate once and keep in KV.
// For a pilot, set both as Worker secrets and these are never used.
async function witnessKey(env) {
  if (env.WITNESS_PRIVATE_JWK) return JSON.parse(env.WITNESS_PRIVATE_JWK);
  let k = await env.WITNESS.get("cfg:witness-key", "json");
  if (!k) { k = (await witnessKeygen()).privateJwk; k.kid = "wit-" + new Date().toISOString().slice(0, 10); await env.WITNESS.put("cfg:witness-key", JSON.stringify(k)); }
  return k;
}
async function presenceSecret(env) {
  if (env.PRESENCE_HMAC) return env.PRESENCE_HMAC;
  let s = await env.WITNESS.get("cfg:presence-secret");
  if (!s) { s = [...crypto.getRandomValues(new Uint8Array(32))].map((b) => b.toString(16).padStart(2, "0")).join(""); await env.WITNESS.put("cfg:presence-secret", s); }
  return s;
}

const VERSION = "0.8";
const SENTENCE = "Sessions to customer endpoints must prove a human or a registered agent with a stated purpose. Existing bot score is evidence. Observe only.";
const MANIFEST = {
  version: 1,
  anchors: { presence: "cloudflare turnstile (siteverify)", agents: "web-bot-auth directories at each agent host", crawlers: "operators' published address lists (openai, google, bing, perplexity)", score: "zone bot management, if any", witness: "ed25519 public key at /__manifest" },
  term: { purposes: ["browse", "compare", "appraise"], validUntil: "2027-01-01" },
};
const INTERNAL = ["/__witness", "/__manifest", "/__dash", "/__presence", "/__mode", DIRECTORY_PATH];
// Sub-resources a page pulls in are not sessions: forward them without evaluation or witness.
const ASSET = /\.(?:js|mjs|css|map|png|jpe?g|gif|webp|avif|svg|ico|woff2?|ttf|otf|eot|webmanifest|mp4|webm|mp3|pdf)$/i;

export default {
  async fetch(req, env, ctx) {
    const url = new URL(req.url);
    const p = url.pathname;
    if (p === "/__dash") return html(DASH);
    if (p === "/__manifest") return manifest(env);
    if (p === "/__witness") return witnessFeed(env, url);
    if (p === "/__presence") return presence(req, env, url);
    if (p === "/__mode") return mode(req, env);
    if (p === "/__reset") return reset(req, env);
    if (p === DIRECTORY_PATH && env.DEMO_AGENT_JWKS) return json(JSON.parse(env.DEMO_AGENT_JWKS));
    if (ASSET.test(p)) return fetch(new Request(env.ORIGIN + p + url.search, req));

    // One witness per session per epoch. Browsers get a session cookie; cookieless clients key on address + user agent.
    const sid = sessionId(req);
    if (sid.cookieless) sid.id = await cookielessId(req);
    const seenKey = "s:" + sid.id + ":" + epoch();
    const seen = await env.WITNESS.get(seenKey);
    // Real-time mechanism: running sums per session, updated on every request the observer receives (constant time).
    const dynKey = "d:" + sid.id;
    const dyn = observe((await env.WITNESS.get(dynKey, "json")) || newDyn(), Date.now() / 1000);
    ctx.waitUntil(env.WITNESS.put(dynKey, JSON.stringify(dyn), { expirationTtl: 1800 }));

    const program = compile(SENTENCE, MANIFEST, { epoch: epoch(), rev: 1 });
    const evidence = await gather(req, env);
    bind(program, evidence);
    const verdict = await evaluate(program, VERIFIERS, { evidence });
    const T = await transcript(program);
    const currentMode = (await env.WITNESS.get("mode")) || "observe";
    const decision = decide(verdict, evidence, currentMode, p, env);
    decision.askSign = decision.bucket === "unattributed" && !!evidence.crawler && !evidence.agent;
    decision.sid = sid.id; decision.stateful = !sid.fresh && !sid.cookieless;
    decision.dyn = dynFeatures(dyn); decision.h = mechanismScore(dyn);
    // Calibration: in step-up mode, an epsilon-random slice of unattributed sessions is asked independently of h,
    // so the outcome curve of h is unbiased (Attribution by Proof, Part IV, Theorem H3).
    const eps = Number(env.STEPUP_EPSILON || 0);
    if (currentMode === "stepup" && decision.action === "allow" && decision.bucket === "unattributed" && !seen && !ASSET.test(p) && eps > 0 && Math.random() < eps) {
      decision.action = "stepup"; decision.result = "STEP-UP"; decision.askedRandom = true;
    }
    if (!seen || decision.action !== "allow") {
      ctx.waitUntil(witness(env, req, program, T, verdict, evidence, decision));
      ctx.waitUntil(env.WITNESS.put(seenKey, "1", { expirationTtl: 120 }));
    }

    if (decision.action === "stepup") return Response.redirect(url.origin + "/__presence?next=" + encodeURIComponent(p + url.search), 302);
    if (decision.action === "refuse") return new Response("no key: " + verdict.why + " · witness " + decision.id, { status: 403, headers: { "x-one-witness": decision.id } });
    const upstream = await fetch(new Request(env.ORIGIN + p + url.search, req));
    const out = new Response(upstream.body, upstream);
    out.headers.set("x-one-bucket", decision.bucket);
    out.headers.set("x-one-witness", decision.id);
    if (sid.fresh) out.headers.append("Set-Cookie", `one_sid=${sid.id}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=86400`);
    // RFC 9421 §5.1: ask unsigned declared crawlers to sign next time. Negotiation, not a wall.
    if (decision.askSign) out.headers.set("Accept-Signature", 'sig1=("@authority" "@method" "@path");tag="web-bot-auth"');
    return out;
  },
};

const epoch = () => Math.floor(Date.now() / 60000);
function sessionId(req) {
  const m = (req.headers.get("cookie") || "").match(/one_sid=([a-f0-9]{16})/);
  if (m) return { id: m[1], fresh: false };
  return { id: [...crypto.getRandomValues(new Uint8Array(8))].map((b) => b.toString(16).padStart(2, "0")).join(""), fresh: true, cookieless: true };
}
async function cookielessId(req) {
  const ip = req.headers.get("cf-connecting-ip") || "";
  const ua = req.headers.get("user-agent") || "";
  const d = new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(ip + "\u0000" + ua)));
  return [...d.slice(0, 8)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

// ---------- evidence: what the request carries ----------
async function gather(req, env) {
  const cf = req.cf || {};
  const ev = { agent: null, human: null, score: cf.botManagement?.score ?? null, country: cf.country || "?", asn: cf.asn || "?", ua: (req.headers.get("user-agent") || "").slice(0, 120), verified: cf.botManagement?.verifiedBot ?? null };
  const agentHost = parseSignatureAgent(req.headers.get("signature-agent"));
  if (agentHost && req.headers.get("signature")) {
    try {
      const scheme = env.DIRECTORY_SCHEME || "https";
      const dir = await fetch(`${scheme}://${agentHost}${DIRECTORY_PATH}`, { cf: { cacheTtl: 3600, cacheEverything: true } });
      if (!dir.ok) ev.agent = { host: agentHost, ok: false, reason: "directory " + dir.status };
      else {
        const jwks = await dir.json();
        const r = await verifyRequest(req, jwks);
        ev.agent = { host: agentHost, ok: r.ok, reason: r.reason, keyid: r.keyid, purpose: jwks.purpose || jwks.web_bot_auth?.purpose || null };
      }
    } catch (e) { ev.agent = { host: agentHost, ok: false, reason: String(e.message || e).slice(0, 80) }; }
  }
  const m = (req.headers.get("cookie") || "").match(/one_presence=(\d+)\.([a-f0-9]+)/);
  if (m && Date.now() - Number(m[1]) < 86400000 && (await hmac(await presenceSecret(env), m[1])) === m[2]) ev.human = { ok: true, since: Number(m[1]) };
  if (!ev.agent?.ok && !ev.human?.ok) {
    try {
      const lists = env.CRAWLER_LISTS_JSON ? JSON.parse(env.CRAWLER_LISTS_JSON) : DEFAULT_LISTS;
      ev.crawler = await verifyCrawler(req.headers.get("cf-connecting-ip") || "", ev.ua, { lists, fetchList: (url) => publishedList(env, url) });
    } catch { ev.crawler = null; }
  }
  return ev;
}

// Operators' published address lists, cached in KV for a day. Unreachable list = no verification (fail closed).
async function publishedList(env, url) {
  const key = "cfg:list:" + url;
  const cached = await env.WITNESS.get(key, "json");
  if (cached) return cached;
  const r = await fetch(url, { cf: { cacheTtl: 86400, cacheEverything: true } });
  if (!r.ok) throw new Error("list " + r.status);
  const json = await r.json();
  await env.WITNESS.put(key, JSON.stringify(json), { expirationTtl: 86400 });
  return json;
}

// The program's identity row is generic ("human or registered agent"); bind the live claim and evidence.
function bind(program, ev) {
  const id = program.rows.find((r) => r.type === "identity");
  if (ev.agent?.ok) { id.claim = "agent:" + ev.agent.host; id.evidence = "web-bot-auth signature · " + ev.agent.keyid; }
  else if (ev.agent && !ev.agent.ok) { id.claim = "agent signature invalid"; id.evidence = ev.agent.reason; }
  else if (ev.human?.ok) { id.claim = "human present"; id.evidence = "turnstile · presence cookie"; }
  else if (ev.crawler?.ok) { id.claim = "crawler:" + ev.crawler.operator; id.evidence = ev.crawler.evidence; }
  else if (ev.crawler) { id.claim = "unresolved"; id.evidence = ev.crawler.evidence; }
  else { id.claim = "unresolved"; id.evidence = ""; }
  const purpose = program.rows.find((r) => r.type === "purpose");
  purpose.claim = ev.agent?.ok ? (ev.agent.purpose || "stated in card") : ev.human?.ok ? "browse" : ev.crawler?.ok ? "crawl" : "unresolved";
  purpose.evidence = ev.agent?.ok ? "signature agent card" : ev.human?.ok ? "session" : ev.crawler?.ok ? "operator's published crawler policy" : "";
  const context = program.rows.find((r) => r.type === "context");
  context.claim = `${ev.country} · AS${ev.asn}`; context.evidence = "edge metadata";
  program.rows.push({ type: "score", claim: ev.score != null ? String(ev.score) : "none", evidence: ev.score != null ? "zone bot management" : "no bot manager on this zone", cls: "F", fail: "refuse" });
}
const VERIFIERS = {
  identity: (r, { evidence }) => (evidence.agent?.ok || evidence.human?.ok || evidence.crawler?.ok) === true,
  purpose: (r) => r.claim !== "unresolved",
  score: () => true,          // evidence, never the gate
  context: () => true,
  lifecycle: () => true,
  epoch: () => true,
  manifest: () => true,
  policy: () => true,
};

function decide(verdict, ev, currentMode, path, env) {
  const bucket = ev.agent?.ok ? "agent" : ev.human?.ok ? "human" : ev.crawler?.ok ? "crawler" : "unattributed";
  const id = crypto.randomUUID().slice(0, 8);
  const onList = (v) => (v || "").split(",").map((s) => s.trim()).filter(Boolean).some((pre) => path.startsWith(pre));
  let action = "allow";
  if (!verdict.ok) {
    if (currentMode === "stepup" && onList(env.STEPUP_PATHS)) action = "stepup";
    else if (currentMode === "enforce" && onList(env.ENFORCE_PATHS)) action = "refuse";
  }
  return { id, bucket, action, mode: currentMode, result: verdict.ok ? "ALLOW" : action === "refuse" ? "REFUSE" : action === "stepup" ? "STEP-UP" : "WOULD-REFUSE" };
}

// ---------- witnesses ----------
async function witness(env, req, program, T, verdict, ev, decision) {
  const url = new URL(req.url);
  const e = epoch();
  const w = {
    id: decision.id, at: new Date().toISOString(), epoch: e, mode: decision.mode, result: decision.result, bucket: decision.bucket,
    failed: verdict.ok ? null : verdict.row.type, index: verdict.ok ? null : verdict.index,
    path: url.pathname, method: req.method, ua: ev.ua, agent: ev.agent?.ok ? ev.agent.host : null,
    crawler: ev.crawler?.ok ? ev.crawler.operator : null, declares: ev.crawler && !ev.crawler.ok ? ev.crawler.operator : null, rev: 1, T,
    sid: decision.sid || null, stateful: !!decision.stateful, asked: decision.askSign ? "sign" : null,
    askedRandom: !!decision.askedRandom, h: decision.h == null ? null : Math.round(decision.h * 100) / 100, dyn: decision.dyn || null,
    rows: program.rows.map((r) => [r.type, r.claim, r.evidence]),
  };
  Object.assign(w, await signWitness(await witnessKey(env), T, verdict, e));
  await env.WITNESS.put("w:" + String(9999999999999 - Date.now()).padStart(13, "0") + ":" + w.id, JSON.stringify(w), { expirationTtl: 60 * 60 * 24 * 30 });
}
async function witnessFeed(env, url) {
  const n = Math.min(Number(url.searchParams.get("n") || 300), 1000);
  const list = await env.WITNESS.list({ prefix: "w:", limit: n });
  const items = (await Promise.all(list.keys.map((k) => env.WITNESS.get(k.name, "json")))).filter(Boolean);
  // Witnesses are immutable; the mechanism estimate keeps running after the witness was written, so the feed joins
  // the live running sums per session (d:<sid>) onto every witness of that session as dynLive / hLive.
  const sids = [...new Set(items.map((w) => w.sid).filter(Boolean))].slice(0, 300);
  const dyns = Object.fromEntries((await Promise.all(sids.map(async (sid) => [sid, await env.WITNESS.get("d:" + sid, "json")]))).filter(([, d]) => d));
  for (const w of items) if (w.sid && dyns[w.sid]) { w.dynLive = dynFeatures(dyns[w.sid]); w.hLive = Math.round(mechanismScore(dyns[w.sid]) * 100) / 100; }
  const counts = { human: 0, agent: 0, crawler: 0, unattributed: 0 };
  for (const w of items) counts[w.bucket] = (counts[w.bucket] || 0) + 1;
  return json({ sentence: SENTENCE, manifest: MANIFEST, mode: (await env.WITNESS.get("mode")) || "observe", counts, witnesses: items });
}
async function manifest(env) {
  const pub = (({ kty, crv, x, kid }) => ({ kty, crv, x, kid }))(await witnessKey(env));
  return json({ version: VERSION, manifest: MANIFEST, sentence: SENTENCE, witnessPublicJwk: pub, verify: "node tools/verify.js proofpack.json" });
}
async function mode(req, env) {
  if (req.method === "GET") return json({ mode: (await env.WITNESS.get("mode")) || "observe" });
  if (!env.ADMIN_TOKEN || req.headers.get("authorization") !== "Bearer " + env.ADMIN_TOKEN) return new Response("unauthorized", { status: 401 });
  const { mode: m } = await req.json();
  if (!["observe", "stepup", "enforce"].includes(m)) return new Response("mode must be observe | stepup | enforce", { status: 400 });
  await env.WITNESS.put("mode", m);
  return json({ mode: m });
}

async function reset(req, env) {
  if (req.method !== "POST") return new Response("POST with Authorization: Bearer ADMIN_TOKEN", { status: 405 });
  if (!env.ADMIN_TOKEN || req.headers.get("authorization") !== "Bearer " + env.ADMIN_TOKEN) return new Response("unauthorized", { status: 401 });
  let removed = 0, cursor;
  do {
    const page = await env.WITNESS.list({ prefix: "w:", limit: 1000, cursor });
    await Promise.all(page.keys.map((k) => env.WITNESS.delete(k.name)));
    removed += page.keys.length; cursor = page.list_complete ? undefined : page.cursor;
  } while (cursor);
  return json({ removed });
}

// ---------- proven human: Turnstile (explicit render, self-diagnosing), then a 24h presence cookie ----------
async function presence(req, env, url) {
  if (req.method === "POST") {
    const form = await req.formData();
    const token = form.get("cf-turnstile-response") || "";
    if (!token) return html(diag("No token reached the server. The widget did not complete; go back and read the status line under the headline."), 400);
    const r = await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify", {
      method: "POST", body: new URLSearchParams({ secret: env.TURNSTILE_SECRET || "", response: token, remoteip: req.headers.get("cf-connecting-ip") || "" }),
    }).then((x) => x.json()).catch((e) => ({ success: false, "error-codes": ["siteverify unreachable: " + e.message] }));
    if (!r.success) return html(diag("Turnstile rejected the token: " + ((r["error-codes"] || []).join(", ") || "unknown") + ". invalid-input-secret means TURNSTILE_SECRET is wrong; hostname-mismatch means this hostname is not on the widget."), 403);
    const ts = String(Date.now());
    return new Response(null, { status: 302, headers: { Location: safeNext(form.get("next")), "Set-Cookie": `one_presence=${ts}.${await hmac(await presenceSecret(env), ts)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=86400` } });
  }
  const sitekey = env.TURNSTILE_SITEKEY || "";
  return html(`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>one · presence</title>
<script src="https://challenges.cloudflare.com/turnstile/v0/api.js?onload=onTurnstileLoad&render=explicit" async defer></script>
<style>body{font-family:Georgia,serif;background:#000;color:#eee;display:grid;place-items:center;min-height:100vh;margin:0;text-align:center;padding:24px}#st{font-family:Menlo,monospace;font-size:12px;color:#9a9a9a;margin-top:14px;max-width:360px}#btn{display:none;margin-top:14px;background:#F2C614;color:#000;border:0;border-radius:22px;padding:12px 20px;font-size:15px;font-weight:700}</style></head>
<body><form method="POST" action="/__presence" id="f"><input type="hidden" name="next" value="${attr(url.searchParams.get("next") || "/")}">
<div style="font-size:26px;margin-bottom:14px">Proving a human is present.</div>
<div id="w"></div>
<button id="btn" type="submit">Continue</button>
<div id="st">loading widget script…</div>
<p style="font-size:14px;color:#9a9a9a">No account, no puzzle, one token. It becomes an identity row for 24 hours.</p></form>
<script>
var st=document.getElementById('st'),key=${JSON.stringify(sitekey)};
function say(t){st.textContent=t}
if(!key)say('TURNSTILE_SITEKEY is not set on the worker (Settings → Variables and Secrets).');
setTimeout(function(){if(!window.turnstile)say('widget script did not load after 6s. Check the network, or a content blocker on this browser.')},6000);
function onTurnstileLoad(){
  if(!key)return;
  say('rendering widget for key '+key.slice(0,8)+'… on '+location.host);
  try{turnstile.render('#w',{sitekey:key,appearance:'always',theme:'dark',callback:function(t){say('token received ('+t.length+' chars). submitting…');document.getElementById('btn').style.display='inline-block';document.getElementById('f').submit()},
    'error-callback':function(c){say('turnstile error '+c+'. 110200 = this hostname is not on the widget; 400020 = site key does not exist; 300xxx = challenge could not run.')},
    'expired-callback':function(){say('token expired, rendering again');turnstile.reset()},
    'timeout-callback':function(){say('challenge timed out, rendering again');turnstile.reset()}});
    say('widget rendered. waiting for Turnstile…')}catch(e){say('render failed: '+e.message)}
}
</script></body></html>`);
}
function diag(msg) { return `<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><body style="font-family:Georgia,serif;background:#000;color:#eee;padding:32px;line-height:1.5"><div style="font-size:22px">Presence not proven.</div><p style="font-family:Menlo,monospace;font-size:13px;color:#F87171;margin-top:12px">${attr(msg)}</p><p><a href="/__presence" style="color:#F2C614">Try again</a></p></body>`; }

// ---------- helpers ----------
const json = (o) => new Response(JSON.stringify(o), { headers: { "content-type": "application/json", "access-control-allow-origin": "*", "cache-control": "no-store" } });
const html = (s, status = 200) => new Response(s, { status, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
const attr = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
const safeNext = (n) => (n && n.startsWith("/") && !n.startsWith("//") ? n : "/");
async function hmac(secret, msg) {
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secret || "dev"), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return [...new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(msg)))].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export { hmac, presenceSecret };
